// === Tab: mySketch ===
let robot
setup=()=>{
  createCanvas(800,400)
  noFill()
  robot=new Robot()
}

class Robot{
  constructor(){
    this.x=-100
    this.y=0
    this.radius=random(25,75)
    this.status='ON'
  }
  update(){
    this.x+=2
    if(this.x>400){this.status='DYING'}
    if(this.x>width+50){this.status='DIE'}
    this.y=noise(frameCount/100)*300
    if(this.status=='DYING'){
      this.y+=this.x-400
    }
  }
  show(){
    ellipse(this.x,this.y,this.radius*2)
  }
  tentacles(){
    for (let j=4; j--; ) {
      const angle=PI/4+TWO_PI/4*j
      let x = this.x + cos(angle) * this.radius
      let y = this.y + sin(angle) * this.radius
      ellipse(x, y, 5)

      let pins=[]
      for(let i=12;i--;){
        pins[i]=createVector(map(i,0,11,-100,width+100)+[10,-10,20,-20][j],150)
      }
      beginShape()
      for (let i = 120; i--;) {
        const angle = pins.reduce((total, e) => 
                      total +  atan2(e.y - y,e.x - x)
                      , 0)       
        vertex(x += cos(angle), y += sin(angle))
        if (pins.some(p => (x - p.x) ** 2 + (y - p.y) ** 2 < 1)) break;
      }
      endShape()
      ellipse(x,y,5)
    }
  }
}

draw = () => {
  background('white')
  stroke('black')
  line(0,150,width,150)

  if(robot.status=='DIE')robot=new Robot()
  robot.update()
  robot.show()
  robot.tentacles()
}
